const n = pieces, nb = max(4, round(n * 0.55)), i = @ptnum;
const sp = sqrt(wall_width * wall_height / n);
let x, y;
if (i < nb) {
  const k = i + 0.5, jit = 0.3 / sqrt(nb);
  x = (clamp(frac(rand(seed, 11) + k * 0.7548776662466927) + (rand(i, seed, 1) - 0.5) * jit, 0.01, 0.99) - 0.5) * wall_width;
  y = clamp(frac(rand(seed, 12) + k * 0.5698402909980532) + (rand(i, seed, 2) - 0.5) * jit, 0.01, 0.99) * wall_height;
} else {
  const K = max(2, round(n / 12)), c = (i - nb) % K;
  const hitc = c === 0 && impact > 0;
  const cx = hitc ? 0 : (rand(c, seed, 21) - 0.5) * wall_width * 0.9;
  const cy = hitc ? wall_height * 0.45 : (0.1 + 0.8 * rand(c, seed, 22)) * wall_height;
  const a = TAU * rand(i, seed, 23), r = sp * (0.05 + 0.4 * sqrt(rand(i, seed, 24)));
  x = clamp(cx + r * cos(a), -0.49 * wall_width, 0.49 * wall_width);
  y = clamp(cy + r * sin(a), 0.01 * wall_height, 0.99 * wall_height);
}
@P = [x, y, (rand(i, seed, 3) - 0.5) * thickness * 0.3];

const seen = new Set();
for (let i = 0; i < nprims(0); i++) seen.add(prim(0, 'part', i));
i@piece_count = seen.size;

const c = prim(0, 'class', pointprims(0, @ptnum)[0]), s = point(1, 'P', c);
const r = rotate(sub(@P, s), PI * rand(c, seed, 34), randdir(c * 7 + seed + 0.5));
@P = add(add(s, r), [0, 0, (rand(c, seed, 35) - 0.5) * 0.6]);

const id = @class, site = point(1, 'P', id);
const hit = [0, wall_height * 0.45, -thickness / 2];
const d = sub(site, hit);
const reach = 0.25 * min(wall_width, 2 * wall_height);
const f = impact * exp(-(d.x * d.x + d.y * d.y) / (reach * reach));
const dir = normalize([d.x * 0.15, 0.3, 1]);
v@v = mul(dir, 6 * f * (0.7 + 0.6 * rand(id, seed, 7)));
v@w = mul(randdir(id * 13 + seed), 1 + 6 * f);

const seen = new Set();
for (let i = 0; i < nprims(0); i++) seen.add(prim(0, 'part', i));
i@piece_count = seen.size;
